import { createHash } from 'node:crypto';
import { readFile } from 'node:fs/promises';
import { posix, resolve } from 'node:path';
import { assertSharedPaths, requireReadyProject } from './core.js';
import { applyChanges, assertSafePath, readTextIfExists, withProjectLock } from './files.js';
import { assertAcceptance, checkGate, inspectConfirmations } from './confirmations.js';

export const templateTypes = [
  'product-requirements', 'product-design', 'module-requirements',
  'module-design', 'change-requirements', 'change-design',
] as const;
export type TemplateType = typeof templateTypes[number];

interface Completion {
  documentHash: string;
  evidence: string;
  evidenceHash: string;
  at: string;
  confirmation?: Awaited<ReturnType<typeof assertAcceptance>>;
}
interface WorkRecord {
  schemaVersion: 1;
  id: string;
  title: string;
  type: TemplateType;
  document: string;
  createdAt: string;
  status: 'draft' | 'complete';
  completion?: Completion;
  completionHistory?: Completion[];
  requirementsBasis?: { workId: string; requestId: string };
}

function fail(code: string, message: string): never {
  throw Object.assign(new Error(message), { code });
}

function validateId(id: string): void {
  if (!/^(?:[0-9]{8}-)?[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/.test(id) || id.length > 64
    || /^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:-|$)/i.test(id)) {
    fail('INVALID_WORK_ID', '工作标识须为 1–64 位小写字母、数字和单个连字符，以字母或 YYYYMMDD-日期前缀开头，不得使用设备保留名。');
  }
}

function hash(content: string): string {
  return createHash('sha256').update(content).digest('hex');
}

function workPaths(id: string, type: TemplateType) {
  validateId(id);
  const directory = `.tiller/work/${id}`;
  return {
    directory,
    record: `${directory}/record.json`,
    notes: `${directory}/work.md`,
    document: `${directory}/${type.endsWith('design') ? 'design' : 'requirements'}.md`,
  };
}

function evidencePath(value: string): string {
  const canonical = value.toLowerCase();
  if (!value || value.includes('\\') || value.startsWith('/') || value.includes(':')
    || value.split('/').some(part => !part || part === '..' || part === '.')
    || !value.endsWith('.md') || canonical.startsWith('.git/') || canonical.startsWith('.tiller/local/')) {
    fail('INVALID_EVIDENCE', '证据须为工程内共享 Markdown 文件的相对路径，使用 / 分隔且不能包含路径穿越。');
  }
  return value;
}

function parseRecord(text: string, id: string): WorkRecord {
  let data: unknown;
  try { data = JSON.parse(text); } catch { fail('INVALID_WORK_RECORD', '工作记录不是有效 JSON。'); }
  if (!data || typeof data !== 'object' || Array.isArray(data)) fail('INVALID_WORK_RECORD', '工作记录格式错误。');
  const value = data as Record<string, unknown>;
  if (value.schemaVersion !== 1 || value.id !== id || typeof value.title !== 'string'
    || !value.title.trim() || typeof value.createdAt !== 'string'
    || !templateTypes.includes(value.type as TemplateType)
    || !['draft', 'complete'].includes(value.status as string)) {
    fail('INVALID_WORK_RECORD', '工作记录版本不受支持或必要字段无效。');
  }
  if (value.document !== workPaths(id, value.type as TemplateType).document) {
    fail('INVALID_WORK_RECORD', '工作产物位置与工作标识不匹配。');
  }
  function validateCompletion(completion: unknown): void {
    if (!completion || typeof completion !== 'object' || Array.isArray(completion)) {
      fail('INVALID_WORK_RECORD', '完成记录缺少证据关联。');
    }
    const item = completion as Record<string, unknown>;
    if (typeof item.evidence !== 'string' || typeof item.at !== 'string'
      || typeof item.documentHash !== 'string' || !/^[a-f0-9]{64}$/.test(item.documentHash)
      || typeof item.evidenceHash !== 'string' || !/^[a-f0-9]{64}$/.test(item.evidenceHash)) {
      fail('INVALID_WORK_RECORD', '完成证据字段无效。');
    }
    evidencePath(item.evidence);
    if (item.confirmation !== undefined) {
      const confirmation = item.confirmation as Record<string, unknown>;
      if (!confirmation || typeof confirmation !== 'object'
        || typeof confirmation.requestId !== 'string' || typeof confirmation.decisionId !== 'string'
        || confirmation.confirmationBasis !== 'reported-review'
        || typeof confirmation.requestFingerprint !== 'string' || typeof confirmation.decisionFingerprint !== 'string') {
        fail('INVALID_WORK_RECORD', '完成记录的人工验收关联无效。');
      }
    }
    if (item.evidence.toLowerCase() === String(value.document).toLowerCase()
      || item.evidence.toLowerCase() === workPaths(id, value.type as TemplateType).notes.toLowerCase()) {
      fail('INVALID_WORK_RECORD', '产物或工作说明本身不能代替独立评审依据。');
    }
  }
  if (value.status === 'complete') validateCompletion(value.completion);
  else if (value.completion !== undefined) fail('INVALID_WORK_RECORD', '草稿不能带有完成结论。');
  if (value.completionHistory !== undefined) {
    if (!Array.isArray(value.completionHistory)) fail('INVALID_WORK_RECORD', '历史完成记录必须为数组。');
    for (const completion of value.completionHistory) validateCompletion(completion);
  }
  if (value.requirementsBasis !== undefined) {
    const basis = value.requirementsBasis as Record<string, unknown>;
    if (!basis || typeof basis !== 'object' || typeof basis.workId !== 'string' || typeof basis.requestId !== 'string') {
      fail('INVALID_WORK_RECORD', '设计的需求确认依据无效。');
    }
    validateId(basis.workId);
  }
  return value as unknown as WorkRecord;
}

async function requireRequirements(root: string, basis?: WorkRecord['requirementsBasis']): Promise<void> {
  if (!basis) fail('REQUIREMENTS_CONFIRMATION_REQUIRED', '创建设计草稿需要 --requirements-work 和 --requirements-request，先确认对应需求。');
  validateId(basis.workId);
  const gate = await checkGate(root, basis.workId, basis.requestId);
  if (gate.gate !== 'requirements' || !gate.confirmed) {
    fail('REQUIREMENTS_CONFIRMATION_REQUIRED', `对应需求尚未有效确认：${gate.issues.join('；')}`);
  }
}

function contentIssues(content: string | null, label: string): string[] {
  if (content === null) return [`${label}不存在。`];
  const issues: string[] = [];
  if (/<!--\s*TODO\b/i.test(content) || /^\s*(?:[-*]\s+)?TODO\b/im.test(content)
    || /\{\{[^}]+\}\}/.test(content)) issues.push(`${label}仍含未填写占位内容。`);
  const visible = content.replace(/<!--[\s\S]*?-->/g, '').trim();
  if (!/^#\s+\S/m.test(visible)) issues.push(`${label}缺少文档标题。`);
  const body = visible.split(/\r?\n/).filter(line => !/^\s*(?:#|>|[-*]\s*$|$)/.test(line)).join('\n').trim();
  if (!body) issues.push(`${label}缺少实际正文。`);
  for (const section of visible.split(/^##\s+/m).slice(1)) {
    const lines = section.split(/\r?\n/);
    const title = lines.shift() ?? '';
    if (!lines.some(line => line.trim() && !/^\s*#/.test(line))) issues.push(`${label}的“${title.trim()}”章节为空。`);
  }
  return issues;
}

export async function createWork(rootInput: string, id: string, title: string, typeInput = 'product-requirements', requirementsBasis?: WorkRecord['requirementsBasis']) {
  validateId(id);
  if (!title.trim() || title.length > 200 || /[\r\n\x00-\x1f]/.test(title)) fail('INVALID_TITLE', '标题须为 1–200 字符的单行文本。');
  if (!templateTypes.includes(typeInput as TemplateType)) fail('INVALID_TEMPLATE', `支持的模板：${templateTypes.join(', ')}`);
  const type = typeInput as TemplateType;
  const root = resolve(rootInput);
  await requireReadyProject(root);
  return withProjectLock(root, async () => {
    await requireReadyProject(root);
    if (type.endsWith('design')) await requireRequirements(root, requirementsBasis);
    else if (requirementsBasis) fail('INVALID_ARGUMENT', '需求确认引用只适用于设计模板。');
    const paths = workPaths(id, type);
    await assertSharedPaths(root, [paths.record, paths.notes, paths.document]);
    for (const path of [paths.record, paths.notes, paths.document]) {
      if (await readTextIfExists(root, path) !== null) fail('WORK_EXISTS', `工作或目标文件已经存在：${path}；请使用 resume 接续。`);
    }
    const template = await readFile(new URL(`../resources/templates/${type}.md`, import.meta.url), 'utf8');
    const document = template.replaceAll('{{title}}', title.trim());
    const record: WorkRecord = {
      schemaVersion: 1, id, title: title.trim(), type,
      document: paths.document, createdAt: new Date().toISOString(), status: 'draft',
      ...(requirementsBasis ? { requirementsBasis } : {}),
    };
    const notes = `# ${title.trim()}\n\n## 目标与授权\n\n起草 ${type} 文档；仅创建草稿，不代表内容已确认或获准实现。按实际用户授权补充范围。\n\n## 依据与产物\n\n- [项目规则索引](../../rules/index.md)\n- [草稿](${posix.basename(paths.document)})\n\n## 进展\n\n已建立草稿骨架，尚未完成内容编写或验证。机器结论保存在 record.json，不将本说明作为验收通过记录。\n\n## 待定问题\n\n需根据已有背景与用户意图明确目标、范围和验收条件，不编造项目事实。\n\n## 下一步\n\n读取项目依据，补充必要信息并编写草稿；保留未决问题，完成后记录针对实际产物的评审依据。\n`;
    await applyChanges(root, [
      { path: paths.document, before: null, after: document },
      { path: paths.notes, before: null, after: notes },
      { path: paths.record, before: null, after: JSON.stringify(record, null, 2) + '\n' },
    ]);
    return { root, id, status: 'draft', document: paths.document, notes: paths.notes };
  });
}

async function loadWork(root: string, id: string, write = false) {
  validateId(id);
  await requireReadyProject(root, { write });
  const recordPath = `.tiller/work/${id}/record.json`;
  const original = await readTextIfExists(root, recordPath);
  if (original === null) fail('WORK_NOT_FOUND', `未找到工作 ${id}。`);
  const record = parseRecord(original, id);
  const paths = workPaths(id, record.type);
  await assertSharedPaths(root, [paths.record, paths.notes, paths.document]);
  const document = await readTextIfExists(root, paths.document);
  const notes = await readTextIfExists(root, paths.notes);
  return { record, original, paths, document, notes };
}

async function evaluate(root: string, data: Awaited<ReturnType<typeof loadWork>>) {
  const issues = [...contentIssues(data.document, '草稿'), ...contentIssues(data.notes, '工作说明')];
  let stale = false;
  let acceptanceStatus = 'not-recorded';
  if (data.record.requirementsBasis) {
    try { await requireRequirements(root, data.record.requirementsBasis); }
    catch (error) { issues.push((error as Error).message); stale = true; }
  }
  if (data.record.status === 'complete' && data.record.completion) {
    const previous = data.record.completion;
    try { await assertSharedPaths(root, [previous.evidence]); }
    catch (error) { issues.push((error as Error).message); }
    const evidence = await readTextIfExists(root, previous.evidence);
    stale = stale || data.document === null || hash(data.document) !== previous.documentHash
      || evidence === null || hash(evidence) !== previous.evidenceHash;
    if (stale) issues.push('产物或验收依据已变化，原完成结论失效；需重新评审并提交新的完成依据。');
    issues.push(...contentIssues(evidence, '验收依据'));
    if (previous.confirmation) {
      try {
        const current = await assertAcceptance(root, data.record.id, previous.confirmation.requestId, data.paths.document, previous.evidence);
        if (JSON.stringify(current) !== JSON.stringify(previous.confirmation)) throw new Error('人工验收决定已变化，需要重新核对交付。');
        acceptanceStatus = 'reported-review';
      } catch (error) {
        stale = true;
        acceptanceStatus = 'needs-review';
        issues.push((error as Error).message);
      }
    } else acceptanceStatus = 'unknown-legacy';
  }
  return {
    status: stale ? 'stale' : data.record.status, ready: issues.length === 0, issues, acceptanceStatus,
    completionKind: data.record.completion && !data.record.completion.confirmation ? 'legacy-document-completion' : 'human-review-record',
    sourceVerification: 'not-independently-verified', automaticTransition: false,
  };
}

export async function resumeWork(rootInput: string, id: string) {
  const root = resolve(rootInput);
  const data = await loadWork(root, id);
  return {
    root, id, title: data.record.title, type: data.record.type,
    ...await evaluate(root, data),
    document: data.paths.document, content: data.document, notes: data.notes,
    confirmations: await inspectConfirmations(root, id),
    limitation: '只读接续；结构检查不代表内容已确认、语义验收通过或产品已经实现。',
  };
}

export async function checkWork(rootInput: string, id: string) {
  const result = await resumeWork(rootInput, id);
  return {
    root: result.root, id, status: result.status, ready: result.ready, issues: result.issues,
    acceptanceStatus: result.acceptanceStatus, completionKind: result.completionKind,
    confirmations: result.confirmations, automaticTransition: false, limitation: result.limitation,
  };
}

export async function completeWork(rootInput: string, id: string, evidenceInput: string, acceptanceRequest?: string) {
  const root = resolve(rootInput);
  const evidenceLocation = evidencePath(evidenceInput);
  await requireReadyProject(root);
  return withProjectLock(root, async () => {
    const data = await loadWork(root, id, true);
    if (evidenceLocation.toLowerCase() === data.paths.document.toLowerCase()
      || evidenceLocation.toLowerCase() === data.paths.notes.toLowerCase()) {
      fail('INVALID_EVIDENCE', '请提供独立的实际评审依据，而不是草稿或工作说明本身。');
    }
    await assertSafePath(root, evidenceLocation);
    await assertSharedPaths(root, [evidenceLocation]);
    const evidence = await readTextIfExists(root, evidenceLocation);
    const issues = [...contentIssues(data.document, '草稿'), ...contentIssues(data.notes, '工作说明'), ...contentIssues(evidence, '验收依据')];
    if (issues.length || data.document === null || evidence === null) fail('WORK_NOT_READY', issues.join('\n'));
    if (!acceptanceRequest) fail('ACCEPTANCE_REQUIRED', '完成工作需要 --acceptance <request-id> 对应的有效人工验收；技术检查通过不代表用户验收。');
    if (data.record.requirementsBasis) await requireRequirements(root, data.record.requirementsBasis);
    const confirmation = await assertAcceptance(root, id, acceptanceRequest, data.paths.document, evidenceLocation);
    const completion = { documentHash: hash(data.document), evidence: evidenceLocation, evidenceHash: hash(evidence), at: new Date().toISOString(), confirmation };
    // Evidence and documents are checked again immediately before the state change.
    if (await readTextIfExists(root, data.paths.document) !== data.document
      || await readTextIfExists(root, evidenceLocation) !== evidence
      || await readTextIfExists(root, data.paths.notes) !== data.notes) {
      fail('CONTENT_CHANGED', '核对期间内容发生变化，请重新检查。');
    }
    const previous = data.record.completion;
    if (previous && previous.documentHash === completion.documentHash
      && previous.evidence === completion.evidence && previous.evidenceHash === completion.evidenceHash
      && JSON.stringify(previous.confirmation) === JSON.stringify(confirmation)) {
      return { root, id, status: 'complete', evidence: evidenceLocation, confirmation, changed: false, automaticTransition: false };
    }
    const completionHistory = [...(data.record.completionHistory ?? []), ...(previous ? [previous] : [])];
    const record: WorkRecord = { ...data.record, status: 'complete', completion, completionHistory };
    const rechecked = await assertAcceptance(root, id, acceptanceRequest, data.paths.document, evidenceLocation);
    if (JSON.stringify(rechecked) !== JSON.stringify(confirmation)) fail('CONTENT_CHANGED', '验收依据在写入前发生变化。');
    await applyChanges(root, [{ path: data.paths.record, before: data.original, after: JSON.stringify(record, null, 2) + '\n' }]);
    return { root, id, status: 'complete', evidence: evidenceLocation, confirmation, sourceVerification: 'not-independently-verified', automaticTransition: false, limitation: '已保存执行者复核的人工验收记录；未独立认证用户身份，不表示规格内容获批、产品实现或发布获准。' };
  });
}
